// The stocked, framed, ready-to-assemble line (YuDeZign Shaker, Slim and Contract).
// Data in src/data/rtaCatalog.ts is generated by scripts/import-rta-catalog.py from the
// website package in the RTA Cabinet Pricing project; never hand-edit the data file.

export interface RtaFinish {
  /** Finish ID from the workbook, e.g. "SHAKER-WHITE". */
  id: string;
  name: string;
  /** Portrait door photo under /public. */
  door: string;
  /** Landscape drawer-front photo under /public. */
  drawer: string;
  /** Flagged on the Finishes sheet as a low-resolution photo to replace. */
  lowRes?: boolean;
}

export interface RtaCabinet {
  /** YuDeZign item code, e.g. "YDS-B30". */
  code: string;
  desc: string;
  category: string;
  /** Section the category belongs to (see RtaLine.sections). */
  section: string;
  w: number | null;
  h: number | null;
  d: number | null;
  doors: number | null;
  drawers: number | null;
  /** Whether the cabinet can ship assembled; null assembled price where it cannot. */
  canAssemble: boolean;
  /** Assembly add-on in dollars, applied per cabinet when shipped assembled. */
  assembly: number;
  /** Retail RTA price per finish, aligned to RtaLine.finishes; null = not offered in that finish. */
  prices: (number | null)[];
  /** Line drawing under /public, or null where the package has none. */
  drawing: string | null;
}

export interface RtaLine {
  id: 'shaker' | 'slim' | 'contract';
  name: string;
  /** One-line description of the collection. */
  blurb: string;
  finishes: RtaFinish[];
  /** Section order for the page, e.g. Base, Wall, Tall, Vanity, Panels & Fillers, Mouldings, Accessories. */
  sections: string[];
  /** Categories in workbook order. */
  categories: string[];
  cabinets: RtaCabinet[];
}

export interface RtaCatalog {
  /** Workbook the data was generated from. */
  builtFrom: string;
  /** Price list version the workbook was built from. */
  priceListVersion: string;
  /** Date the site data was generated. */
  generated: string;
  /** Sales tax percentage added at checkout. */
  salesTaxPct: number;
  /** Delivery charge per trip in Greater Houston, in dollars. */
  deliveryGreaterHouston: number;
  lines: RtaLine[];
}
